namespace ghidra.pcode.exec;



using ghidra.app.plugin.processors.sleigh;
using ghidra.program.model.pcode;

/**
 * A Sleigh userop definition with one signature
 */
public class FixedSleighPcodeUseropDefinition : AbstractSleighPcodeUseropDefinition {
	protected SignatureDef definition;

	protected FixedSleighPcodeUseropDefinition(string name, SignatureDef definition) : base(name)
    {
		this.definition = definition;
	}

	/* @Override */
	public int getInputCount() {
		return definition.signature().size() - 1; // account for __op_output 
	}

	/**
	 * Get the single signature and definition
	 * 
	 * @return the definition
	 */
	public SignatureDef getSignatureDef() {
		return definition;
	}

	/* @Override */
	public string getBody(List<Varnode> args) {
		return definition.generateBody(args);
	}

	/* @Override */
	public PcodeProgram programFor(SleighLanguage language, List<Varnode> args,
			PcodeUseropLibrary<object> library) {
		return cacheByArgs.computeIfAbsent(args,
			a => SleighProgramCompiler.compileUserop(language, name, definition.signature(),
				definition.generateBody(a), library, a));
	}
}
